/**
 * Attachment storage port (PRD §5.10).
 *
 * The domain never sees absolute filesystem paths. It refers to stored files by a relative
 * storage key generated by the store itself, so user-provided file names can never influence
 * where bytes are written (prevents traversal and overwrite attacks).
 *
 * Writes are two-phase: `stage` copies bytes and verifies the checksum, then the caller commits
 * metadata in a database transaction and finally calls `promote`. Interrupted operations leave
 * staged files that startup reconciliation removes.
 */

export interface StagedAttachment {
  /** Generated relative storage key, e.g. `ab/3f9c….bin`. Never derived from the original name. */
  readonly storageKey: string;
  readonly byteSize: number;
  /** Lowercase hex SHA-256 of the copied bytes. */
  readonly sha256: string;
}

/** Opaque reference to a source file the user selected through a native dialog. */
export interface AuthorizedSourceFile {
  readonly token: string;
}

export interface AttachmentStore {
  /** Copies the selected file into the staging area and verifies its checksum. */
  stage(source: AuthorizedSourceFile, maxBytes: number): Promise<StagedAttachment>;
  /** Makes a staged file part of the managed attachment directory. */
  promote(storageKey: string): Promise<void>;
  /** Removes a staged or managed file. Missing files are not an error (idempotent cleanup). */
  remove(storageKey: string): Promise<void>;
}
